        return 0;
    }

    vector<tuple<int, int, int, int>> candidates;

    // Add the original rectangle
    candidates.push_back( make_tuple(x_min_m, x_max_m, y_min_m, y_max_m) );

    // Generate candidates for each sardine in the original rectangle
    for (auto& p : sardines) {
        if (p.x >= x_min_m && p.x <= x_max_m && p.y >= y_min_m && p.y <= y_max_m) {
            // Adjust x_high to p.x - 1
            int new_x_low = x_min_m;
            int new_x_high = p.x - 1;
            if (new_x_high >= new_x_low) {
                candidates.push_back( make_tuple(new_x_low, new_x_high, y_min_m, y_max_m) );
            }

            // Adjust x_low to p.x + 1
            new_x_low = p.x + 1;
            new_x_high = x_max_m;
            if (new_x_low <= new_x_high) {
                candidates.push_back( make_tuple(new_x_low, new_x_high, y_min_m, y_max_m) );
            }

            // Adjust y_high to p.y - 1
            int new_y_low = y_min_m;
            int new_y_high = p.y - 1;
            if (new_y_high >= new_y_low) {
                candidates.push_back( make_tuple(x_min_m, x_max_m, new_y_low, new_y_high) );
            }

            // Adjust y_low to p.y + 1
            new_y_low = p.y + 1;
            new_y_high = y_max_m;
            if (new_y_low <= new_y_high) {
                candidates.push_back( make_tuple(x_min_m, x_max_m, new_y_low, new_y_high) );
            }
        }
    }

    // Now evaluate all candidates
    int best_score = -1;
    tuple<int, int, int, int> best_rect;

    for (auto rect : candidates) {
        int x_low, x_high, y_low, y_high;
        tie(x_low, x_high, y_low, y_high) = rect;

        int a = 0;
        for (auto& p : mackerels) {
            if (p.x >= x_low && p.x <= x_high && p.y >= y_low && p.y <= y_high) {
                a++;
            }
        }

        int b = 0;
        for (auto& p : sardines) {
            if (p.x >= x_low && p.x <= x_high && p.y >= y_low && p.y <= y_high) {
                b++;
            }
        }

        int score = a - b;
        if (score > best_score) {
            best_score = score;
            best_rect = rect;
        }
    }

    // Output the best rectangle
    int x_low, x_high, y_low, y_high;
    tie(x_low, x_high, y_low, y_high) = best_rect;

    cout << 4 << endl;
    cout << x_low << " " << y_low << endl;
    cout << x_high << " " << y_low << endl;
    cout << x_high << " " << y_high << endl;
    cout << x_low << " " << y_high << endl;

    return 0;
}

