        points.push_back({x, y});
    }

    mackerels.assign(points.begin(), points.begin() + N);
    sardines.assign(points.begin() + N, points.end());

    int x_min_m = INT_MAX, x_max_m = INT_MIN, y_min_m = INT_MAX, y_max_m = INT_MIN;
    for (const auto& p : mackerels) {
