            x2a = x_max_m;
            y1a = y_min_m;
            y2a = y_max_m;
            if (x1a <= x2a && y1a <= y2a) {
                int a = countInside(mackerels, x1a, y1a, x2a, y2a);
                int b = countInside(sardines, x1a, y1a, x2a, y2a);
                int diff = a - b;
                if (diff > best_a_minus_b) {
                    best_a_minus_b = diff;
                    best_x1 = x1a;
                    best_x2 = x2a;
                    best_y1 = y1a;
                    best_y2 = y2a;
                }
            }

            // Adjust y to exclude s.y by setting y_max = s.y - 1
            x1a = x_min_m;
            x2a = x_max_m;
            y1a = y_min_m;
            y2a = s.y - 1;
            if (x1a <= x2a && y1a <= y2a) {
                int a = countInside(mackerels, x1a, y1a, x2a, y2a);
                int b = countInside(sardines, x1a, y1a, x2a, y2a);
                int diff = a - b;
                if (diff > best_a_minus_b) {
                    best_a_minus_b = diff;
                    best_x1 = x1a;
                    best_x2 = x2a;
                    best_y1 = y1a;
                    best_y2 = y2a;
                }
            }

            // Adjust y to exclude s.y by setting y_min = s.y + 1
            x1a = x_min_m;
            x2a = x_max_m;
            y1a = s.y + 1;
            y2a = y_max_m;
            if (x1a <= x2a && y1a <= y2a) {
                int a = countInside(mackerels, x1a, y1a, x2a, y2a);
                int b = countInside(sardines, x1a, y1a, x2a, y2a);
                int diff = a - b;
                if (diff > best_a_minus_b) {
                    best_a_minus_b = diff;
                    best_x1 = x1a;
                    best_x2 = x2a;
                    best_y1 = y1a;
                    best_y2 = y2a;
                }
            }
        }
    }

    if (initial_diff > best_a_minus_b) {
        best_a_minus_b = initial_diff;
        best_x1 = x_min_m;
        best_x2 = x_max_m;
        best_y1 = y_min_m;
        best_y2 = y_max_m;
    }

    if (best_a_minus_b <= 0) {
        best_x1 = x_min_m;
        best_x2 = x_max_m;
        best_y1 = y_min_m;
        best_y2 = y_max_m;
    }

    cout << 4 << endl;
    cout << best_x1 << " " << best_y1 << endl;
    cout << best_x2 << " " << best_y1 << endl;
    cout << best_x2 << " " << best_y2 << endl;
    cout << best_x1 << " " << best_y2 << endl;

    return 0;
}

