#include <bits/stdc++.h>
using namespace std;

int main() {
    int N;
    cin >> N;
    vector<pair<int, int>> mackerels;
    vector<pair<int, int>> sardines;
    for (int i = 0; i < 2 * N; ++i) {
        int x, y;
        cin >> x >> y;
        if (i < N) {
            mackerels.push_back({x, y});
        } else {
            sardines.push_back({x, y});
        }
    }

    // Precompute sorted x and y for mackerels
    vector<int> sorted_x_m;
    vector<int> sorted_y_m;
    for (auto &p : mackerels) {
        sorted_x_m.push_back(p.first);
        sorted_y_m.push_back(p.second);
    }
    sort(sorted_x_m.begin(), sorted_x_m.end());
    sort(sorted_y_m.begin(), sorted_y_m.end());

    // Compute initial rectangle
    int min_x = mackerels[0].first;
    int max_x = mackerels[0].first;
    int min_y = mackerels[0].second;
    int max_y = mackerels[0].second;
    for (auto &p : mackerels) {
        min_x = min(min_x, p.first);
        max_x = max(max_x, p.first);
        min_y = min(min_y, p.second);
        max_y = max(max_y, p.second);
    }

    vector<tuple<int, int, int, int>> candidates;
    candidates.push_back({min_x, max_x, min_y, max_y});

    // Process each sardine
    for (auto &s : sardines) {
        int x_s = s.first;
        int y_s = s.second;
        // Check if it's inside initial rectangle
        if (x_s >= min_x && x_s <= max_x && y_s >= min_y && y_s <= max_y) {
            // Try to adjust each boundary
            // Adjust max_x
            int target_x = x_s - 1;
            auto it = upper_bound(sorted_x_m.begin(), sorted_x_m.end(), target_x);
            if (it != sorted_x_m.begin()) {
                --it;
                int new_max_x = *it;
                if (new_max_x < max_x) {
                    candidates.push_back({min_x, new_max_x, min_y, max_y});
                }
            }
            // Adjust min_x
            target_x = x_s + 1;
            auto it_min = lower_bound(sorted_x_m.begin(), sorted_x_m.end(), target_x);
            if (it_min != sorted_x_m.end()) {
                int new_min_x = *it_min;
                if (new_min_x > min_x) {
                    candidates.push_back({new_min_x, max_x, min_y, max_y});
                }
            }
            // Adjust max_y
            int target_y = y_s - 1;
            auto it_y = upper_bound(sorted_y_m.begin(), sorted_y_m.end(), target_y);
            if (it_y != sorted_y_m.begin()) {
                --it_y;
                int new_max_y = *it_y;
                if (new_max_y < max_y) {
                    candidates.push_back({min_x, max_x, min_y, new_max_y});
                }
            }
            // Adjust min_y
            target_y = y_s + 1;
            auto it_y_min = lower_bound(sorted_y_m.begin(), sorted_y_m.end(), target_y);
            if (it_y_min != sorted_y_m.end()) {
                int new_min_y = *it_y_min;
                if (new_min_y > min_y) {
                    candidates.push_back({min_x, max_x, new_min_y, max_y});
                }
            }
        }
    }

    // Now evaluate all candidates
    double best_diff = -1e18;
    tuple<int, int, int, int> best_rect;
    for (auto &rect : candidates) {
        int rx1, rx2, ry1, ry2;
        tie(rx1, rx2, ry1, ry2) = rect;
        // Count mackerels in this rect
        int a = 0;
        for (auto &p : mackerels) {
            if (p.first >= rx1 && p.first <= rx2 && p.second >= ry1 && p.second <= ry2) {
                a++;
            }
        }
        // Count sardines in this rect
        int b = 0;
        for (auto &s : sardines) {
            if (s.first >= rx1 && s.first <= rx2 && s.second >= ry1 && s.second <= ry2) {
                b++;
            }
        }
        double current_diff = a - b;
        if (current_diff > best_diff) {
            best_diff = current_diff;
            best_rect = rect;
        }
    }

    // Output the best_rect
    auto [rx1, rx2, ry1, ry2] = best_rect;
    cout << 4 << endl;
    cout << rx1 << " " << ry1 << endl;
    cout << rx2 << " " << ry1 << endl;
    cout << rx2 << " " << ry2 << endl;
    cout << rx1 << " " << ry2 << endl;
    return 0;
}

