    // Now, try to improve the rectangle
    int current_x_left = x_left;
    int current_x_right = x_right;
    int current_y_bottom = y_bottom;
    int current_y_top = y_top;
    int current_score = N - initial_sardines; // a - b

    while (true) {
        // FIND SARDINES INSIDE CURRENT RECTANGLE
        vector<pair<int, int>> sardines_in_current;
        for (const auto& s : sardines) {
            if (s.first >= current_x_left && s.first <= current_x_right &&
