                            b_new++;
                        }
                    }
                    int score = a_new - b_new;
                    if (score > best_score) {
                        best_score = score;
                        best_y_top = new_y_top;
                        improved = true;
                    }
                }
            }

            // Try to move bottom boundary to sy + 1
            int new_y_bottom = sy + 1;
            if (new_y_bottom < best_y_top) {
