#include <bits/stdc++.h>
using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);

    int N;
    cin >> N;

    vector<pair<int, int>> mackerels;
    vector<pair<int, int>> sardines;

    for (int i = 0; i < 2 * N; ++i) {
        int x, y;
        cin >> x >> y;
        if (i < N) {
            mackerels.push_back({x, y});
        } else {
            sardines.push_back({x, y});
        }
    }

    // Sort mackerels and sardines by x, then y
    sort(mackerels.begin(), mackerels.end(), [](const pair<int, int>& a, const pair<int, int>& b) {
        if (a.first != b.first) return a.first < b.first;
        return a.second < b.second;
    });
    sort(sardines.begin(), sardines.end(), [](const pair<int, int>& a, const pair<int, int>& b) {
        if (a.first != b.first) return a.first < b.first;
        return a.second < b.second;
    });

    // Helper functions for binary search
    auto find_left_x = [](vector<pair<int, int>>& vec, int x_min) {
        int l = 0, r = vec.size();
        while (l < r) {
            int mid = (l + r) / 2;
            if (vec[mid].first < x_min) {
                l = mid + 1;
            } else {
                r = mid;
            }
        }
        return l;
    };

    auto find_right_x = [](vector<pair<int, int>>& vec, int x_max) {
        int l = 0, r = vec.size();
        while (l < r) {
            int mid = (l + r) / 2;
            if (vec[mid].first <= x_max) {
                l = mid + 1;
            } else {
                r = mid;
            }
        }
        return l;
    };

    // Function to count points inside [x_min, x_max] and [y_min, y_max]
    auto count_points = [&](vector<pair<int, int>>& points, int x_min, int x_max, int y_min, int y_max) {
        int start = find_left_x(points, x_min);
        int end = find_right_x(points, x_max);
        int cnt = 0;
        for (int i = start; i < end; ++i) {
            if (points[i].second >= y_min && points[i].second <= y_max) {
                ++cnt;
            }
        }
        return cnt;
    };

    // Compute initial rectangle for mackerels
    int min_x_m = mackerels[0].first;
    int max_x_m = mackerels[0].first;
    int min_y_m = mackerels[0].second;
    int max_y_m = mackerels[0].second;

    for (auto& p : mackerels) {
        min_x_m = min(min_x_m, p.first);
        max_x_m = max(max_x_m, p.first);
        min_y_m = min(min_y_m, p.second);
        max_y_m = max(max_y_m, p.second);
    }

    // Initial score
    int initial_m_count = count_points(mackerels, min_x_m, max_x_m, min_y_m, max_y_m);
    int initial_s_count = count_points(sardines, min_x_m, max_x_m, min_y_m, max_y_m);
    int best_score = max(0, initial_m_count - initial_s_count + 1);
    int best_xmin = min_x_m;
    int best_xmax = max_x_m;
    int best_ymin = min_y_m;
    int best_ymax = max_y_m;

    // Find sardines in the initial rectangle
    int start_s = find_left_x(sardines, min_x_m);
    int end_s = find_right_x(sardines, max_x_m);
    vector<pair<int, int>> sardines_in_initial;
    for (int i = start_s; i < end_s; ++i) {
        if (sardines[i].second >= min_y_m && sardines[i].second <= max_y_m) {
            sardines_in_initial.push_back(sardines[i]);
        }
    }

    // Process each sardine in the initial rectangle
    for (auto& s : sardines_in_initial) {
        int xs = s.first;
        int ys = s.second;

        // Variation 1: increase x_min to xs + 1
        int new_xmin1 = xs + 1;
        int new_xmax1 = max_x_m;
        int new_ymin1 = min_y_m;
        int new_ymax1 = max_y_m;
        if (new_xmin1 <= new_xmax1) {
            int m_count = count_points(mackerels, new_xmin1, new_xmax1, new_ymin1, new_ymax1);
            int s_count = count_points(sardines, new_xmin1, new_xmax1, new_ymin1, new_ymax1);
            int score = max(0, m_count - s_count + 1);
            if (score > best_score) {
                best_score = score;
                best_xmin = new_xmin1;
                best_xmax = new_xmax1;
                best_ymin = new_ymin1;
                best_ymax = new_ymax1;
            }
        }

        // Variation 2: decrease x_max to xs - 1
        int new_xmin2 = min_x_m;
        int new_xmax2 = xs - 1;
        int new_ymin2 = min_y_m;
        int new_ymax2 = max_y_m;
        if (new_xmin2 <= new_xmax2) {
            int m_count = count_points(mackerels, new_xmin2, new_xmax2, new_ymin2, new_ymax2);
            int s_count = count_points(sardines, new_xmin2, new_xmax2, new_ymin2, new_ymax2);
            int score = max(0, m_count - s_count + 1);
            if (score > best_score) {
                best_score = score;
                best_xmin = new_xmin2;
                best_xmax = new_xmax2;
                best_ymin = new_ymin2;
                best_ymax = new_ymax2;
            }
        }

        // Variation 3: increase y_min to ys + 1
        int new_xmin3 = min_x_m;
        int new_xmax3 = max_x_m;
        int new_ymin3 = ys + 1;
        int new_ymax3 = max_y_m;
        if (new_ymin3 <= new_ymax3) {
            int m_count = count_points(mackerels, new_xmin3, new_xmax3, new_ymin3, new_ymax3);
            int s_count = count_points(sardines, new_xmin3, new_xmax3, new_ymin3, new_ymax3);
            int score = max(0, m_count - s_count + 1);
            if (score > best_score) {
                best_score = score;
                best_xmin = new_xmin3;
                best_xmax = new_xmax3;
                best_ymin = new_ymin3;
                best_ymax = new_ymax3;
            }
        }

        // Variation 4: decrease y_max to ys - 1
        int new_xmin4 = min_x_m;
        int new_xmax4 = max_x_m;
        int new_ymin4 = min_y_m;
        int new_ymax4 = ys - 1;
        if (new_ymin4 <= new_ymax4) {
            int m_count = count_points(mackerels, new_xmin4, new_xmax4, new_ymin4, new_ymax4);
            int s_count = count_points(sardines, new_xmin4, new_xmax4, new_ymin4, new_ymax4);
            int score = max(0, m_count - s_count + 1);
            if (score > best_score) {
                best_score = score;
                best_xmin = new_xmin4;
                best_xmax = new_xmax4;
                best_ymin = new_ymin4;
                best_ymax = new_ymax4;
            }
        }
    }

    // Output the best rectangle
    cout << 4 << endl;
    cout << best_xmin << " " << best_ymin << endl;
    cout << best_xmax << " " << best_ymin << endl;
    cout << best_xmax << " " << best_ymax << endl;
    cout << best_xmin << " " << best_ymax << endl;

    return 0;
}

