        }
    }

    vector<tuple<int, int, int, int>> candidates;

    // Add initial rectangle
    candidates.push_back({min_x_m, max_x_m, min_y_m, max_y_m});

    // Generate candidates by excluding each sardine
    for (auto& s : sardines_in_rect) {
