vector<Point> getSortedPoints(const vector<Point>& points) {
    vector<Point> sortedPoints = points;
    sort(sortedPoints.begin(), sortedPoints.end(), [](const Point& a, const Point& b) {
        return a.x < b.x || (a.x == b.x && a.y < b.y);
    });
    return sortedPoints;
}

// Return the number of points in the given rectangle [x1, x2] x [y1, y2]
int countInside(const vector<Point>& points, int x1, int y1, int x2, int y2) {
    int cnt = 0;
    for (const auto& p : points) {
        if (p.x >= x1 && p.x <= x2 && p.y >= y1 && p.y <= y2) {
            cnt++;
        }
    }
    return cnt;
}

