                    best_x1 = x1a;
                    best_x2 = x2a;
                    best_y1 = y1a;
                    best_y2 = y2a;
                }
            }
        }
    }

    if (!S.empty()) {
        int min_sx = INT_MAX;
        int max_sx = INT_MIN;
        int min_sy = INT_MAX;
        int max_sy = INT_MIN;
        for (const auto& s : S) {
            min_sx = min(min_sx, s.x);
            max_sx = max(max_sx, s.x);
            min_sy = min(min_sy, s.y);
            max_sy = max(max_sy, s.y);
        }

        // Adjust y to exclude sardines on bottom edge
        int y1a = min_sy + 1;
        int y2a = y_max_m;
        if (y1a <= y2a) {
            int a = countInside(mackerels, x_min_m, y1a, x_max_m, y2a);
            int b = countInside(sardines, x_min_m, y1a, x_max_m, y2a);
            int diff = a - b;
            if (diff > best_a_minus_b) {
                best_a_minus_b = diff;
                best_x1 = x_min_m;
                best_x2 = x_max_m;
                best_y1 = y1a;
                best_y2 = y2a;
            }
        }

        // Adjust y to exclude sardines on top edge
        y1a = y_min_m;
        y2a = max_sy - 1;
        if (y1a <= y2a) {
