                    best_x_left = current_x_left;
                    best_x_right = current_x_right;
                    best_y_bottom = new_y_bottom;
                    best_y_top = current_y_top;
                }
            }

            // Try to move top boundary
            int new_y_top = min(current_y_top, s.second - 1);
            if (current_x_left < current_x_right && current_y_bottom < new_y_top) {
                int a_new = 0, b_new = 0;
