#include <algorithm>
#include <numeric>
#include <limits>
#include <cstdint>
using namespace std;

struct Point {
    int64_t x;
    int64_t y;
};

// Function to count points inside [xL, xR] x [yB, yT]
int count_points(vector<Point>& pts, int64_t xL, int64_t xR, int64_t yB, int64_t yT) {
    vector<int64_t> ys;
    int l = 0, r = pts.size();
    while (l < r) {
        int mid = (l + r) / 2;
        if (pts[mid].x < xL) l = mid + 1;
        else r = mid;
    }
    int end = l;
    l = 0;
    r = pts.size();
    while (l < r) {
        int mid = (l + r) / 2;
        if (pts[mid].x > xR) r = mid;
        else l = mid + 1;
    }
    int start = l;
    for (int i = start; i < end; ++i) {
        ys.push_back(pts[i].y);
    }
    sort(ys.begin(), ys.end());
    auto it_low = lower_bound(ys.begin(), ys.end(), yB);
    auto it_high = upper_bound(ys.begin(), ys.end(), yT);
    return it_high - it_low;
}

