};

int main() {
    int N;
    cin >> N;
    vector<Point> mackerels;
    vector<Point> sardines;
    for (int i = 0; i < 2 * N; ++i) {
        int x, y;
        cin >> x >> y;
        if (i < N) {
            mackerels.emplace_back(x, y);
        } else {
            sardines.emplace_back(x, y);
        }
    }

    vector<Point> sorted_mackerels(mackerels);
    sort(sorted_mackerels.begin(), sorted_mackerels.end(), [](const Point& a, const Point& b) {
        return a.x < b.x || (a.x == b.x && a.y < b.y);
    });

    vector<Point> sorted_sardines(sardines);
    sort(sorted_sardines.begin(), sorted_sardines.end(), [](const Point& a, const Point& b) {
        return a.x < b.x || (a.x == b.x && a.y < b.y);
    });

    int x_left = numeric_limits<int>::max();
    int x_right = numeric_limits<int>::min();
    int y_bottom = numeric_limits<int>::max();
    int y_top = numeric_limits<int>::min();

    for (const auto& p : mackerels) {
        x_left = min(x_left, p.x);
        x_right = max(x_right, p.x);
        y_bottom = min(y_bottom, p.y);
        y_top = max(y_top, p.y);
    }

    auto count_mackerels = [&](int x_min, int x_max, int y_min, int y_max) {
        int count = 0;
        auto it = lower_bound(sorted_mackerels.begin(), sorted_mackerels.end(), Point{x_min, 0},
                              [](const Point& a, const Point& b) {
                                  return a.x < b.x || (a.x == b.x && a.y < b.y);
                              });
        auto end = upper_bound(sorted_mackerels.begin(), sorted_mackerels.end(), Point{x_max, 100000},
                               [](const Point& a, const Point& b) {
                                   return a.x < b.x || (a.x == b.x && a.y < b.y);
                               });
        for (auto current = it; current != end; ++current) {
            if (current->y >= y_min && current->y <= y_max) {
                count++;
            }
        }
        return count;
    };

    auto count_sardines = [&](int x_min, int x_max, int y_min, int y_max) {
        int count = 0;
        auto it = lower_bound(sorted_sardines.begin(), sorted_sardines.end(), Point{x_min, 0},
                              [](const Point& a, const Point& b) {
                                  return a.x < b.x || (a.x == b.x && a.y < b.y);
                              });
        auto end = upper_bound(sorted_sardines.begin(), sorted_sardines.end(), Point{x_max, 100000},
                               [](const Point& a, const Point& b) {
                                   return a.x < b.x || (a.x == b.x && a.y < b.y);
                               });
        for (auto current = it; current != end; ++current) {
            if (current->y >= y_min && current->y <= y_max) {
                count++;
            }
        }
        return count;
    };

    int a = count_mackerels(x_left, x_right, y_bottom, y_top);
    int b = count_sardines(x_left, x_right, y_bottom, y_top);
    if (b == 0) {
        cout << 4 << endl;
        cout << x_left << " " << y_bottom << endl;
        cout << x_right << " " << y_bottom << endl;
        cout << x_right << " " << y_top << endl;
        cout << x_left << " " << y_top << endl;
        return 0;
    }

    int best_x_left = x_left;
    int best_x_right = x_right;
    int best_y_bottom = y_bottom;
    int best_y_top = y_top;
    int best_score = a - b;

    bool improved;
    do {
        improved = false;
        vector<Point> current_sardines;
        auto it = lower_bound(sorted_sardines.begin(), sorted_sardines.end(), Point{best_x_left, 0},
                              [](const Point& a, const Point& b) {
                                  return a.x < b.x || (a.x == b.x && a.y < b.y);
                              });
        auto end = upper_bound(sorted_sardines.begin(), sorted_sardines.end(), Point{best_x_right, 100000},
                               [](const Point& a, const Point& b) {
                                   return a.x < b.x || (a.x == b.x && a.y < b.y);
                               });
        for (auto current = it; current != end; ++current) {
            if (current->y >= best_y_bottom && current->y <= best_y_top) {
                current_sardines.push_back(*current);
            }
        }

        if (current_sardines.empty()) {
            break;
        }

        for (const auto& s : current_sardines) {
            // Try to move x_left to s.x + 1
            int new_x_left = s.x + 1;
            int new_x_right = best_x_right;
            int new_y_bottom = best_y_bottom;
            int new_y_top = best_y_top;
            if (new_x_left < new_x_right && new_y_bottom < new_y_top) {
                int a_new = count_mackerels(new_x_left, new_x_right, new_y_bottom, new_y_top);
                int b_new = count_sardines(new_x_left, new_x_right, new_y_bottom, new_y_top);
                int score = a_new - b_new;
                if (score > best_score) {
                    best_score = score;
                    best_x_left = new_x_left;
                    best_x_right = new_x_right;
                    best_y_bottom = new_y_bottom;
                    best_y_top = new_y_top;
                    improved = true;
                }
            }

            // Try to move x_right to s.x - 1
            int new_left = best_x_left;
            int new_right = s.x - 1;
            if (new_left < new_right && best_y_bottom < best_y_top) {
                int a_new = count_mackerels(new_left, new_right, best_y_bottom, best_y_top);
                int b_new = count_sardines(new_left, new_right, best_y_bottom, best_y_top);
                int score = a_new - b_new;
                if (score > best_score) {
                    best_score = score;
                    best_x_left = new_left;
                    best_x_right = new_right;
                    best_y_bottom = best_y_bottom;
                    best_y_top = best_y_top;
                    improved = true;
                }
            }

            // Try to move y_bottom to s.y + 1
            int new_y_bottom_y = s.y + 1;
            if (new_y_bottom_y < best_y_top) {
                int a_new = count_mackerels(best_x_left, best_x_right, new_y_bottom_y, best_y_top);
                int b_new = count_sardines(best_x_left, best_x_right, new_y_bottom_y, best_y_top);
                int score = a_new - b_new;
                if (score > best_score) {
                    best_score = score;
                    best_x_left = best_x_left;
                    best_x_right = best_x_right;
                    best_y_bottom = new_y_bottom_y;
                    best_y_top = best_y_top;
                    improved = true;
                }
            }

            // Try to move y_top to s.y - 1
            int new_y_top_y = s.y - 1;
            if (new_y_top_y > best_y_bottom) {
                int a_new = count_mackerels(best_x_left, best_x_right, best_y_bottom, new_y_top_y);
                int b_new = count_sardines(best_x_left, best_x_right, best_y_bottom, new_y_top_y);
                int score = a_new - b_new;
                if (score > best_score) {
                    best_score = score;
                    best_x_left = best_x_left;
                    best_x_right = best_x_right;
                    best_y_bottom = best_y_bottom;
                    best_y_top = new_y_top_y;
                    improved = true;
                }
            }
        }
    } while (improved);

    cout << 4 << endl;
