        if (i < N) {
            mackerels.emplace_back(x, y);
        } else {
            sardines.emplace_back(x, y);
        }
    }

    // Compute initial bounding box for mackerels
    int m_x_min = INT_MAX, m_x_max = INT_MIN;
    int m_y_min = INT_MAX, m_y_max = INT_MIN;
    for (auto [x, y] : mackerels) {
        m_x_min = min(m_x_min, x);
        m_x_max = max(m_x_max, x);
        m_y_min = min(m_y_min, y);
        m_y_max = max(m_y_max, y);
    }

    int best_score = -1;
    int best_x1 = 0, best_y1 = 0, best_x2 = 0, best_y2 = 0;

    // Function to calculate score and check if the rectangle is valid
    auto evaluate = [&](int x1, int y1, int x2, int y2) {
        int a = 0, b = 0;
        for (auto [x, y] : mackerels) {
            if (x >= x1 && x <= x2 && y >= y1 && y <= y2) {
                a++;
            }
        }
        for (auto [x, y] : sardines) {
            if (x >= x1 && x <= x2 && y >= y1 && y <= y2) {
                b++;
            }
        }
        int perimeter = 2 * (abs(x2 - x1) + abs(y2 - y1));
        if (perimeter <= 400000) {
            int score = max(0, a - b + 1);
            return score;
        }
        return -1;
    };

