    vector<pair<int, int>> s_in_initial;
    for (const auto& s : sardines) {
        if (s.first >= x_left && s.first <= x_right && s.second >= y_bottom && s.second <= y_top) {
            s_in_initial.push_back(s);
        }
    }
    int initial_sardines = s_in_initial.size();
    current_score -= initial_sardines;

    if (initial_sardines == 0) {
