                }
            }
        }

        // Try to adjust bottom boundary
        int min_s_y = numeric_limits<int>::max();
        for (const auto& s : sardines_in_current) {
            min_s_y = min(min_s_y, s.second);
        }
        if (min_s_y > current_y_bottom) {
