                    best_x_right = current_x_right;
                    best_y_bottom = new_y_bottom;
                    best_y_top = current_y_top;
                }
            }
        }

        // Try to adjust top boundary
        int max_s_y = numeric_limits<int>::min();
        for (const auto& s : sardines_in_current) {
            max_s_y = max(max_s_y, s.second);
        }
        if (max_s_y < current_y_top) {
            int new_y_top = max_s_y - 1;
            if (current_y_bottom < new_y_top && current_x_left < current_x_right) {
