#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
#include <functional>
#include <numeric>
using namespace std;

int count_in_rect(const vector<pair<int, int>>& points_sorted, const vector<int>& x_coords, int minx, int maxx, int miny, int maxy) {
    int count = 0;
    auto it_left = lower_bound(x_coords.begin(), x_coords.end(), minx);
    auto it_right = upper_bound(x_coords.begin(), x_coords.end(), maxx);
    int start_idx = it_left - x_coords.begin();
    int end_idx = it_right - x_coords.begin();
    for (int i = start_idx; i < end_idx; ++i) {
        if (points_sorted[i].second >= miny && points_sorted[i].second <= maxy) {
            count++;
        }
    }
    return count;
}

int main() {
    int N;
    cin >> N;
    vector<pair<int, int>> mackerels, sardines;
    for (int i = 0; i < 2 * N; ++i) {
        int x, y;
        cin >> x >> y;
        if (i < N) {
            mackerels.push_back({x, y});
        } else {
            sardines.push_back({x, y});
        }
    }

    // Sort fish by x and y to enable efficient range queries
    sort(mackerels.begin(), mackerels.end(), [](const pair<int, int>& a, const pair<int, int>& b) {
        if (a.first != b.first) return a.first < b.first;
        return a.second < b.second;
    });
    sort(sardines.begin(), sardines.end(), [](const pair<int, int>& a, const pair<int, int>& b) {
        if (a.first != b.first) return a.first < b.first;
        return a.second < b.second;
    });

    // Prepare x-coordinate lists for binary search
    vector<int> x_coords_mackerels;
    for (auto& p : mackerels) {
        x_coords_mackerels.push_back(p.first);
    }
    vector<int> x_coords_sardines;
    for (auto& p : sardines) {
        x_coords_sardines.push_back(p.first);
    }

    // Compute bounding boxes for all mackerels and sardines
    int min_x_mack = mackerels[0].first, max_x_mack = mackerels[0].first;
    int min_y_mack = mackerels[0].second, max_y_mack = mackerels[0].second;
    for (auto& p : mackerels) {
        min_x_mack = min(min_x_mack, p.first);
        max_x_mack = max(max_x_mack, p.first);
        min_y_mack = min(min_y_mack, p.second);
        max_y_mack = max(max_y_mack, p.second);
    }

    int min_x_sard = sardines[0].first, max_x_sard = sardines[0].first;
    int min_y_sard = sardines[0].second, max_y_sard = sardines[0].second;
    for (auto& p : sardines) {
        min_x_sard = min(min_x_sard, p.first);
        max_x_sard = max(max_x_sard, p.first);
        min_y_sard = min(min_y_sard, p.second);
        max_y_sard = max(max_y_sard, p.second);
    }

    // Initialize with the bounding box of all fish
    int current_minx = min(min_x_mack, min_x_sard);
    int current_maxx = max(max_x_mack, max_x_sard);
    int current_miny = min(min_y_mack, min_y_sard);
    int current_maxy = max(max_y_mack, max_y_sard);

    // Adjust the initial rectangle to fit within the perimeter limit
    int W = current_maxx - current_minx;
    int H = current_maxy - current_miny;
    int perimeter = 2 * (W + H);
    if (perimeter > 400000) {
        int max_allowed_sum = 200000;      // 400000 / 2
        int sum = W + H;
        int need_reduce = sum - max_allowed_sum;

        if (need_reduce > 0) {
            // Try to reduce width first
            int new_W = W - need_reduce;
            if (new_W < 0) new_W = 0;

            if (new_W >= 0) {
                current_maxx = current_minx + new_W;
            } else {
                // Reduce height
                int new_H = H - (need_reduce - W);
                if (new_H < 0) new_H = 0;
                current_maxy = current_miny + new_H;
            }
        }
    }

    // Main optimization loop
    int current_diff = count_in_rect(mackerels, x_coords_mackerels, current_minx, current_maxx, current_miny, current_maxy)
                       - count_in_rect(sardines, x_coords_sardines, current_minx, current_maxx, current_miny, current_maxy);

    bool improved = true;
    while (improved) {
        improved = false;

        vector<pair<int, int>> sardines_in_current;
        for (auto& s : sardines) {
            if (s.first >= current_minx && s.first <= current_maxx && s.second >= current_miny && s.second <= current_maxy) {
                sardines_in_current.push_back(s);
            }
        }

        if (sardines_in_current.empty()) {
            break;
        }

        int best_diff_new = -1;
        int best_new_minx = current_minx, best_new_maxx = current_maxx;
        int best_new_miny = current_miny, best_new_maxy = current_maxy;

        for (auto& s : sardines_in_current) {
            int sx = s.first;
            int sy = s.second;

            // Try shifting left
            int new_minx1 = sx + 1, new_maxx1 = current_maxx;
            if (new_minx1 <= new_maxx1) {
                int total_length1 = 2 * (new_maxx1 - new_minx1) + 2 * (current_maxy - current_miny);
                if (total_length1 <= 400000) {
                    int a1 = count_in_rect(mackerels, x_coords_mackerels, new_minx1, new_maxx1, current_miny, current_maxy);
                    int b1 = count_in_rect(sardines, x_coords_sardines, new_minx1, new_maxx1, current_miny, current_maxy);
                    int diff1 = a1 - b1;
                    if (diff1 > best_diff_new) {
                        best_diff_new = diff1;
                        best_new_minx = new_minx1;
                        best_new_maxx = new_maxx1;
                        best_new_miny = current_miny;
                        best_new_maxy = current_maxy;
                    }
                }
            }

            // Try shifting right
            int new_minx2 = current_minx, new_maxx2 = sx - 1;
            if (new_maxx2 >= new_minx2) {
                int total_length2 = 2 * (new_maxx2 - new_minx2) + 2 * (current_maxy - current_miny);
                if (total_length2 <= 400000) {
