#include <cmath>
#include <functional>
using namespace std;

int count_in_rect(const vector<pair<int, int>>& points, const vector<int>& x_coords, int minx, int maxx, int miny, int maxy) {
    int count = 0;
    auto it_left = lower_bound(x_coords.begin(), x_coords.end(), minx);
    auto it_right = upper_bound(x_coords.begin(), x_coords.end(), maxx);
    int start_idx = it_left - x_coords.begin();
    int end_idx = it_right - x_coords.begin();
    for (int i = start_idx; i < end_idx; ++i) {
        if (points[i].second >= miny && points[i].second <= maxy) {
            count++;
        }
    }
    return count;
}

