        }

        int new_x_max_e2 = min_x_s - 1;
        int new_y_max_e2 = min_y_s - 1;
        if (new_x_max_e2 >= x_min_m && new_x_max_e2 > x_min_m && new_y_max_e2 >= y_min_m && new_y_max_e2 > y_min_m) {
