// Function to count points in a rectangle
int count_points(const vector<pair<int, int>>& sorted_points, int x1, int x2, int y1, int y2) {
    int n = sorted_points.size();
    int left = 0;
    int right = n;
    while (left < right) {
        int mid = (left + right) / 2;
        if (sorted_points[mid].first >= x1) {
            right = mid;
        } else {
            left = mid + 1;
        }
    }
    int start_idx = left;

    left = 0;
    right = n;
    while (left < right) {
        int mid = (left + right) / 2;
        if (sorted_points[mid].first <= x2) {
            left = mid + 1;
        } else {
            right = mid;
        }
    }
    int end_idx = left - 1;

    if (start_idx > end_idx) {
        return 0;
    }

    int count = 0;
    for (int i = start_idx; i <= end_idx; ++i) {
        if (sorted_points[i].second >= y1 && sorted_points[i].second <= y2) {
            count++;
        }
    }
    return count;
}

