        return a.second < b.second;
    });

    sort(sardines.begin(), sardines.end(), [](const pair<int, int>& a, const pair<int, int>& b) {
        if (a.first != b.first) return a.first < b.first;
        return a.second < b.second;
    });

    // Prepare x-coordinate lists
    vector<int> x_coords_mackerels;
    for (auto& p : mackerels) {
        x_coords_mackerels.push_back(p.first);
    }

    vector<int> x_coords_sardines;
    for (auto& p : sardines) {
        x_coords_sardines.push_back(p.first);
    }

