// Function to count points within a rectangle
int count_in_rect(const vector<pair<int, int>>& points, const vector<int>& x_coords, int minx, int maxx, int miny, int maxy) {
    int count = 0;
    auto it_left = lower_bound(x_coords.begin(), x_coords.end(), minx);
    auto it_right = upper_bound(x_coords.begin(), x_coords.end(), maxx);
    int start_idx = it_left - x_coords.begin();
    int end_idx = it_right - x_coords.begin();
    for (int i = start_idx; i < end_idx; ++i) {
        if (points[i].second >= miny && points[i].second <= maxy) {
            count++;
        }
    }
    return count;
}

int main() {
    int N;
    cin >> N;
    vector<pair<int, int>> mackerels, sardines;
    for (int i = 0; i < 2 * N; ++i) {
        int x, y;
        cin >> x >> y;
        if (i < N) {
            mackerels.push_back({x, y});
        } else {
            sardines.push_back({x, y});
        }
    }

    // Sort the points for efficient querying
    sort(mackerels.begin(), mackerels.end(), [](const pair<int, int>& a, const pair<int, int>& b) {
        if (a.first != b.first) return a.first < b.first;
        return a.second < b.second;
    });

    sort(sardines.begin(), sardines.end(), [](const pair<int, int>& a, const pair<int, int>& b) {
        if (a.first != b.first) return a.first < b.first;
        return a.second < b.second;
    });

    // Prepare x-coordinate lists
    vector<int> x_coords_mackerels;
    for (auto& p : mackerels) {
        x_coords_mackerels.push_back(p.first);
    }

    vector<int> x_coords_sardines;
    for (auto& p : sardines) {
        x_coords_sardines.push_back(p.first);
    }

    // Determine initial rectangle
    int min_x_mack = mackerels[0].first;
    int max_x_mack = mackerels[0].first;
    int min_y_mack = mackerels[0].second;
    int max_y_mack = mackerels[0].second;

    for (auto& p : mackerels) {
        min_x_mack = min(min_x_mack, p.first);
        max_x_mack = max(max_x_mack, p.first);
        min_y_mack = min(min_y_mack, p.second);
        max_y_mack = max(max_y_mack, p.second);
    }

    int current_minx = min_x_mack;
    int current_maxx = max_x_mack;
    int current_miny = min_y_mack;
    int current_maxy = max_y_mack;

    int perimeter = 2 * ((current_maxx - current_minx) + (current_maxy - current_miny));
    if (perimeter > 4e5) {
        current_minx = 0;
        current_maxx = 1e5;
        current_miny = 0;
        current_maxy = 1e5;
        perimeter = 2 * ((current_maxx - current_minx) + (current_maxy - current_miny));
    }

    // Initial score
    int current_diff = count_in_rect(mackerels, x_coords_mackerels, current_minx, current_maxx, current_miny, current_maxy)
                       - count_in_rect(sardines, x_coords_sardines, current_minx, current_maxx, current_miny, current_maxy);

    bool improved = true;
    while (improved) {
