                        best_new_minx = new_minx1;
                        best_new_maxx = new_maxx1;
                        best_new_miny = current_miny;
                        best_new_maxy = current_maxy;
                    }
                }

                // Try to shift left
                int new_minx2 = current_minx, new_maxx2 = sx - 1;
                if (new_maxx2 >= new_minx2) {
                    int a2 = count_in_rect(mackerels, x_coords_mackerels, new_minx2, new_maxx2, current_miny, current_maxy);
                    int b2 = count_in_rect(sardines, x_coords_sardines, new_minx2, new_maxx2, current_miny, current_maxy);
                    int diff = a2 - b2;
