                    if (new_perimeter <= 4e5 && diff > best_diff_new) {
                        best_diff_new = diff;
                        best_new_minx = new_minx2;
                        best_new_maxx = new_maxx2;
                        best_new_miny = current_miny;
                        best_new_maxy = current_maxy;
                    }
                }

                // Try to shift up
                int new_miny3 = sy + 1, new_maxy3 = current_maxy;
                if (new_miny3 <= new_maxy3) {
                    int a3 = count_in_rect(mackerels, x_coords_mackerels, current_minx, current_maxx, new_miny3, new_maxy3);
                    int b3 = count_in_rect(sardines, x_coords_sardines, current_minx, current_maxx, new_miny3, new_maxy3);
                    int diff = a3 - b3;
                    int new_perimeter = 2 * ((current_maxx - current_minx) + (new_maxy3 - new_miny3));
                    if (new_perimeter <= 4e5 && diff > best_diff_new) {
                        best_diff_new = diff;
                        best_new_minx = current_minx;
                        best_new_maxx = current_maxx;
                        best_new_miny = new_miny3;
                        best_new_maxy = new_maxy3;
                    }
                }

                // Try to shift down
                int new_maxy4 = sy - 1, new_miny4 = current_miny;
                if (new_maxy4 >= new_miny4) {
                    int a4 = count_in_rect(mackerels, x_coords_mackerels, current_minx, current_maxx, new_miny4, new_maxy4);
                    int b4 = count_in_rect(sardines, x_coords_sardines, current_minx, current_maxx, new_miny4, new_maxy4);
