                }
            }
        }

        if (best_diff_new > current_diff) {
            current_minx = best_new_minx;
            current_maxx = best_new_maxx;
            current_miny = best_new_miny;
            current_maxy = best_new_maxy;
            current_diff = best_diff_new;
