#include <iostream>
#include <vector>
#include <algorithm>
#include <numeric>
#include <limits>
#include <cmath>
#include <unordered_map>
#include <array>
using namespace std;

int main() {
    int N;
    cin >> N;
    vector<pair<int, int>> mackerels;
    vector<pair<int, int>> sardines;
    for (int i = 0; i < 2 * N; ++i) {
        int x, y;
        cin >> x >> y;
        if (i < N) {
            mackerels.emplace_back(x, y);
        } else {
            sardines.emplace_back(x, y);
        }
    }

    // Compute initial rectangle for mackerels
    int x_left = numeric_limits<int>::max();
    int x_right = numeric_limits<int>::min();
    int y_bottom = numeric_limits<int>::max();
    int y_top = numeric_limits<int>::min();

    for (const auto& p : mackerels) {
        x_left = min(x_left, p.first);
        x_right = max(x_right, p.first);
        y_bottom = min(y_bottom, p.second);
        y_top = max(y_top, p.second);
    }

    // Function to count number of mackerels and sardines inside a rectangle
    auto countInside = [&](int xl, int xr, int yb, int yt) -> pair<int, int> {
        int a = 0, b = 0;
        for (const auto& p : mackerels) {
            if (p.first >= xl && p.first <= xr && p.second >= yb && p.second <= yt) {
                a++;
            }
        }
        for (const auto& p : sardines) {
            if (p.first >= xl && p.first <= xr && p.second >= yb && p.second <= yt) {
                b++;
            }
        }
        return {a, b};
    };

    // Initial best score
    auto [a, b] = countInside(x_left, x_right, y_bottom, y_top);
    int best_score = a - b;
    int current_x_left = x_left;
    int current_x_right = x_right;
    int current_y_bottom = y_bottom;
    int current_y_top = y_top;

    // Loop to improve the rectangle
    int iteration = 0;
    while (iteration < 100) {  // Limit iterations to prevent infinite loop
        vector<pair<int, int>> current_sardines;
        for (const auto& s : sardines) {
            if (s.first >= current_x_left && s.first <= current_x_right && s.second >= current_y_bottom && s.second <= current_y_top) {
                current_sardines.push_back(s);
            }
        }
        if (current_sardines.empty()) {
            break;
        }

        int best_new_score = best_score;
        int new_x_l = current_x_left;
        int new_x_r = current_x_right;
        int new_y_b = current_y_bottom;
        int new_y_t = current_y_top;

        for (const auto& s : current_sardines) {
            int sx = s.first;
            int sy = s.second;

            // Try move left to sx + 1
            int new_left = sx + 1;
            if (new_left < current_x_right) {
                auto [a_new, b_new] = countInside(new_left, current_x_right, current_y_bottom, current_y_top);
                if (a_new - b_new > best_new_score) {
                    best_new_score = a_new - b_new;
                    new_x_l = new_left;
                    new_x_r = current_x_right;
                    new_y_b = current_y_bottom;
                    new_y_t = current_y_top;
                }
            }

            // Try move right to sx - 1
            int new_right = sx - 1;
            if (new_right > current_x_left) {
                auto [a_new, b_new] = countInside(current_x_left, new_right, current_y_bottom, current_y_top);
                if (a_new - b_new > best_new_score) {
                    best_new_score = a_new - b_new;
                    new_x_l = current_x_left;
                    new_x_r = new_right;
                    new_y_b = current_y_bottom;
                    new_y_t = current_y_top;
                }
            }

            // Try move bottom to sy + 1
            int new_bottom = sy + 1;
            if (new_bottom < current_y_top) {
                auto [a_new, b_new] = countInside(current_x_left, current_x_right, new_bottom, current_y_top);
                if (a_new - b_new > best_new_score) {
                    best_new_score = a_new - b_new;
                    new_x_l = current_x_left;
                    new_x_r = current_x_right;
                    new_y_b = new_bottom;
                    new_y_t = current_y_top;
                }
            }

            // Try move top to sy - 1
            int new_top = sy - 1;
            if (new_top > current_y_bottom) {
                auto [a_new, b_new] = countInside(current_x_left, current_x_right, current_y_bottom, new_top);
                if (a_new - b_new > best_new_score) {
                    best_new_score = a_new - b_new;
                    new_x_l = current_x_left;
                    new_x_r = current_x_right;
                    new_y_b = current_y_bottom;
                    new_y_t = new_top;
                }
            }
        }

        if (best_new_score > best_score) {
            best_score = best_new_score;
            current_x_left = new_x_l;
            current_x_right = new_x_r;
            current_y_bottom = new_y_b;
            current_y_top = new_y_t;
        } else {
            break;
        }
        iteration++;
    }

    // Output the best rectangle
    cout << 4 << endl;
    cout << current_x_left << " " << current_y_bottom << endl;
    cout << current_x_right << " " << current_y_bottom << endl;
    cout << current_x_right << " " << current_y_top << endl;
    cout << current_x_left << " " << current_y_top << endl;
    return 0;
}

