                    m_right++;
                }
                if (m.second == current_y_bottom && m.first >= current_x_left && m.first <= current_x_right) {
                    m_bottom++;
                }
                if (m.second == current_y_top && m.first >= current_x_left && m.first <= current_x_right) {
                    m_top++;
                }
            }
        }

        int s_max = max({s_left, s_right, s_bottom, s_top});
        bool edge_found = false;

        if (s_left > s_right && s_left > s_bottom && s_left > s_top) {
            // Move left edge right
            current_x_left += 1;
            a -= m_left;
            b -= s_left;
            edge_found = true;
        } else if (s_right > s_left && s_right > s_bottom && s_right > s_top) {
            // Move right edge left
            current_x_right -= 1;
            a -= m_right;
            b -= s_right;
            edge_found = true;
