        } else if (s_top > s_left && s_top > s_right && s_top > s_bottom) {
            // Move top down
            current_y_top -= 1;
            a -= m_top;
            b -= s_top;
            edge_found = true;
        } else {
            break;
        }

        if (!edge_found) {
            break;
        }

        // Update best score
        int score = max(0, a - b + 1);
        if (score > best_score) {
            best_score = score;
        }
    }

