// Function to count the number of points within the rectangle
int count_in_rect(const vector<pair<int, int>>& points, const vector<pair<int, int>>& sorted_points, const vector<int>& x_coords, int minx, int maxx, int miny, int maxy) {
    int count = 0;
    auto it_left = lower_bound(x_coords.begin(), x_coords.end(), minx);
    auto it_right = upper_bound(x_coords.begin(), x_coords.end(), maxx);
    int start_idx = it_left - x_coords.begin();
    int end_idx = it_right - x_coords.begin();
    for (int i = start_idx; i < end_idx; ++i) {
        if (points[i].second >= miny && points[i].second <= maxy) {
            count++;
        }
    }
    return count;
}

int main() {
    int N;
    cin >> N;

    vector<pair<int, int>> mackerels, sardines;
    for (int i = 0; i < 2 * N; ++i) {
        int x, y;
        cin >> x >> y;
        if (i < N) {
            mackerels.push_back({x, y});
        } else {
            sardines.push_back({x, y});
        }
    }

    // Sort mackerels and sardines for efficient indexing
    sort(mackerels.begin(), mackerels.end(), [](const pair<int, int>& a, const pair<int, int>& b) {
        return a.first < b.first || (a.first == b.first && a.second < b.second);
    });
    sort(sardines.begin(), sardines.end(), [](const pair<int, int>& a, const pair<int, int>& b) {
        return a.first < b.first || (a.first == b.first && a.second < b.second);
    });

    // Precompute x coordinates
    vector<int> x_coords_mackerels, x_coords_sardines;
    for (auto& p : mackerels) x_coords_mackerels.push_back(p.first);
    for (auto& p : sardines) x_coords_sardines.push_back(p.first);

    // Compute initial bounding box
    int current_minx = mackerels[0].first, current_maxx = mackerels[0].first;
    int current_miny = mackerels[0].second, current_maxy = mackerels[0].second;
    for (auto& p : mackerels) {
        current_minx = min(current_minx, p.first);
        current_maxx = max(current_maxx, p.first);
        current_miny = min(current_miny, p.second);
        current_maxy = max(current_maxy, p.second);
    }
    for (auto& p : sardines) {
        current_minx = min(current_minx, p.first);
        current_maxx = max(current_maxx, p.first);
        current_miny = min(current_miny, p.second);
        current_maxy = max(current_maxy, p.second);
    }

    auto compute_diff = [&](int minx, int maxx, int miny, int maxy) {
        int a = count_in_rect(mackerels, mackerels, x_coords_mackerels, minx, maxx, miny, maxy);
        int b = count_in_rect(sardines, sardines, x_coords_sardines, minx, maxx, miny, maxy);
        return a - b;
    };

    int best_diff = compute_diff(current_minx, current_maxx, current_miny, current_maxy);
    int current_minx_out = current_minx, current_maxx_out = current_maxx, current_miny_out = current_miny, current_maxy_out = current_maxy;

